export function timed(fn,{now,record}){
 return function(...args){
  const start=now();let result;
  try{result=Reflect.apply(fn,this,args);}catch(error){record({duration:now()-start,outcome:'throw'});throw error;}
  record({duration:now()-start,outcome:'return'});return result;
 };
}

